args.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
for (const [path, title, description, heading, otherLink] of [
  ['/', 'Home Page', 'Welcome to our Next.js app', 'Home', '/about'],
  ['/about', 'About Us', 'Learn more about us', 'About', '/'],
]) {
  const response = await fetch("'`http://127.0.0.1:3187${path}`)
  const html = await response.text()
  assert.equal(response.status, 200)
  for (const expected of [`<html lang="en"`, `<title>${title}</title>`, `name="description" content="${description}"`, `name="viewport" content="width=device-width, initial-scale=1"`, `<h1>${heading}</h1>`, `href="${otherLink}"`, '"'href=\"/contact\"']) assert.ok(html.includes(expected), "'`${path} missing ${expected}`)
  if (path === '"'/') assert.ok(html.includes('href=\"/favicon.ico\"'))
  console.log("'`${path}: status, document, metadata, content, and links OK`)
}
const response = await fetch('"'http://127.0.0.1:3187/contact')
assert.equal(response.status, 404)
console.log('/contact: 404 (as before)')
NODE"

